import{_ as t,o as i,c as a,a5 as e}from"./chunks/framework.BZzouRtU.js";const r="/study/images/graphics/shader-first-steps.svg",g=JSON.parse('{"title":"シェーダーの第一歩 — 頂点から三角形の色を作る","description":"","frontmatter":{"title":"シェーダーの第一歩 — 頂点から三角形の色を作る","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"graphics","summary":"三角形を描く例から、頂点シェーダー、ラスタライゼーション、補間、フラグメントシェーダーを追う。GLSLとHLSLの型や演算を読み、値を変えて見た目を変える。","aliases":["シェーダー","シェーダ","shader","頂点シェーダー","Vertex Shader","ピクセルシェーダー","Fragment Shader","GLSL","HLSL","UV","補間","mix","lerp"],"verification":"KhronosのGLSL ES 3.00仕様とMicrosoftの描画パイプライン・HLSL資料に照合（2026-11-07）"}},"headers":[],"relativePath":"graphics/shader/shader-first-steps.md","filePath":"graphics/shader/shader-first-steps.md"}'),d={name:"graphics/shader/shader-first-steps.md"};function h(o,s,n,l,p,c){return i(),a("div",null,[...s[0]||(s[0]=[e('<h1 id="シェーダーの第一歩-—-頂点から三角形の色を作る" tabindex="-1">シェーダーの第一歩 — 頂点から三角形の色を作る <a class="header-anchor" href="#シェーダーの第一歩-—-頂点から三角形の色を作る" aria-label="Permalink to &quot;シェーダーの第一歩 — 頂点から三角形の色を作る&quot;">​</a></h1><p>三角形を右へ動かし、表面に色のグラデーションを付ける場面を考えます。<strong>シェーダー</strong>は、描画の途中で位置や色などを計算するプログラムです。CPU側のアプリが使うデータと描画の指示を用意し、GPU側が設定されたシェーダーを実行します。ここでは、頂点シェーダーとフラグメントシェーダーを使う三角形描画を追います。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/overviews-direct3d-11-graphics-pipeline" target="_blank" rel="noreferrer">Microsoftの描画パイプライン</a></p><h2 id="位置を決める処理と、色を作る処理" tabindex="-1">位置を決める処理と、色を作る処理 <a class="header-anchor" href="#位置を決める処理と、色を作る処理" aria-label="Permalink to &quot;位置を決める処理と、色を作る処理&quot;">​</a></h2><table tabindex="0"><thead><tr><th>段階</th><th>受け取るもの</th><th>主な仕事</th></tr></thead><tbody><tr><td><strong>頂点入力</strong></td><td>位置、UVなどの頂点データ。</td><td>描画で使う頂点の属性を渡す。</td></tr><tr><td><strong>頂点シェーダー（VS）</strong></td><td>入力した頂点の属性、共通の設定。</td><td>頂点の出力位置を計算し、UVなどを後段へ渡す。</td></tr><tr><td><strong>三角形の組み立て・ラスタライゼーション</strong></td><td>頂点シェーダーの出力。</td><td>三角形が画面のどこを覆うか調べ、途中の属性を補間する。</td></tr><tr><td><strong>フラグメントシェーダー（FS）</strong></td><td>補間されたUVなど、共通の設定。</td><td>描画候補の色などを計算する。Direct3DではPixel Shaderとも呼ぶ。</td></tr><tr><td><strong>深度・ブレンドなど</strong></td><td>色や深度、描画先の内容。</td><td>採用する値を判定し、必要なら色を混ぜて画像を更新する。</td></tr></tbody></table><figure class="study-figure"><img src="'+r+`" alt="CPUが三角形の頂点と共通設定を用意する。頂点シェーダーが位置とUVを出力し、ラスタライザーが三角形を組み立ててUVを補間する。フラグメントシェーダーが色を計算し、深度やブレンドの処理を経て画像になる。" width="760" height="492" loading="lazy"><figcaption>三角形を描くための概念図です。深度判定の一部を先に行う構成など、実際の処理順には最適化もあります。<a href="/study/images/graphics/shader-first-steps.svg" target="_blank" rel="noopener noreferrer">シェーダーの処理図を拡大</a></figcaption></figure><p>フラグメントは、物体が画面を覆う場所について計算する描画候補です。シェーダーが色を返しても、深度判定などで画像へ残らない場合があります。また、物体の重なりやサンプル単位の実行、補助的な実行などがあるため、見えている画素数とFSの実行回数は必ずしも一致しません。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/d3d10-graphics-programming-guide-rasterizer-stage-rules" target="_blank" rel="noreferrer">Microsoftのラスタライズと補助的な実行</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/d3d10-graphics-programming-guide-output-merger-stage" target="_blank" rel="noreferrer">深度と出力の処理</a></p><h2 id="頂点シェーダーで、三角形を右へ動かす" tabindex="-1">頂点シェーダーで、三角形を右へ動かす <a class="header-anchor" href="#頂点シェーダーで、三角形を右へ動かす" aria-label="Permalink to &quot;頂点シェーダーで、三角形を右へ動かす&quot;">​</a></h2><p>実践では、各頂点へ2次元の位置<code>a_position</code>とUV座標<code>a_uv</code>を渡します。WebGL 2のGLSL ES 3.00で、処理の中心は次のように書けます。これは説明用の抜粋です。</p><div class="language-glsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">glsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gl_Position</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> vec4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(a_position </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> vec2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(u_offset, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">v_uv </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a_uv;</span></span></code></pre></div><p><code>u_offset</code>をX位置に足すと、三角形全体が横へ動きます。<code>gl_Position</code>へ書く値は<strong>クリップ座標</strong>です。この例では<code>w</code>を<code>1</code>にして、入力した2次元の位置をそのまま扱いやすくしています。3Dの物体では、モデル、カメラ、投影の変換を組み合わせて出力位置を作ります。<a href="https://registry.khronos.org/OpenGL/specs/es/3.0/GLSL_ES_Specification_3.00.pdf" target="_blank" rel="noreferrer">KhronosのGLSL ESの頂点出力</a> · <a href="/study/graphics/basics/transforms-and-cameras.html">座標とカメラの基礎</a></p><p>CPU側は、頂点の並びや形式を用意して描画を依頼します。頂点シェーダーの中では、渡された頂点について出力を計算します。UVも出力すると、ラスタライザーが三角形の内部へつなぎ、FSがその場所の値を受け取れます。<a href="https://learn.microsoft.com/en-us/windows/win32/direct3d11/vertex-shader-stage" target="_blank" rel="noreferrer">Microsoftの頂点シェーダーステージ</a></p><h2 id="uvを、そのまま赤と緑に使う" tabindex="-1">UVを、そのまま赤と緑に使う <a class="header-anchor" href="#uvを、そのまま赤と緑に使う" aria-label="Permalink to &quot;UVを、そのまま赤と緑に使う&quot;">​</a></h2><p>三角形のUVを、左下<code>(0, 0)</code>、右下<code>(1, 0)</code>、上<code>(0.5, 1)</code>とします。この例は各頂点の<code>w</code>がすべて<code>1</code>なので、途中のUVは画面上で線形に変わります。Uを赤、Vを緑、青を<code>0.25</code>にすると、その変化を色で見られます。テクスチャを読まず、座標から直接色を作る例です。<a href="https://registry.khronos.org/OpenGL/specs/es/3.0/GLSL_ES_Specification_3.00.pdf" target="_blank" rel="noreferrer">KhronosのGLSL ESの補間規則</a></p><div class="language-glsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">glsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">vec3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> mix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vec3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vec3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(v_uv, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), u_useUv);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">outColor </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> vec4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> u_tint, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>vec3(v_uv, 0.25)</code>は、UVの二つの値と青の値を組み合わせた3成分です。<code>u_useUv</code>を<code>0</code>にすると白、<code>1</code>にするとUVからの色を選びます。さらに<code>u_tint</code>のRGBを掛け、色合いを変えます。<code>outColor</code>の4番目の成分は、この例では<code>1</code>に固定したアルファです。</p><h2 id="glslとhlslの短い式を読む" tabindex="-1">GLSLとHLSLの短い式を読む <a class="header-anchor" href="#glslとhlslの短い式を読む" aria-label="Permalink to &quot;GLSLとHLSLの短い式を読む&quot;">​</a></h2><table tabindex="0"><thead><tr><th>したいこと</th><th>GLSL</th><th>HLSL</th></tr></thead><tbody><tr><td>浮動小数点の値を持つ</td><td><code>float</code></td><td><code>float</code></td></tr><tr><td>2・3・4成分をまとめる</td><td><code>vec2</code>・<code>vec3</code>・<code>vec4</code></td><td><code>float2</code>・<code>float3</code>・<code>float4</code></td></tr><tr><td>4成分からRGBを取り出す</td><td><code>color.rgb</code></td><td><code>color.rgb</code></td></tr><tr><td>二つの値を割合で混ぜる</td><td><code>mix(a, b, t)</code></td><td><code>lerp(a, b, t)</code></td></tr><tr><td>値を0〜1へ収める</td><td><code>clamp(x, 0.0, 1.0)</code></td><td><code>saturate(x)</code></td></tr></tbody></table><p><code>.rgb</code>や<code>.xy</code>のように成分を選ぶ書き方を<strong>スウィズル</strong>と呼びます。数値の割合を使う<code>mix</code>や<code>lerp</code>は、<code>t = 0</code>なら<code>a</code>、<code>t = 1</code>なら<code>b</code>、その間なら二つを混ぜます。割合を0〜1へ収める必要がある場合は、別に<code>clamp</code>などを使います。<a href="https://registry.khronos.org/OpenGL/specs/es/3.0/GLSL_ES_Specification_3.00.pdf" target="_blank" rel="noreferrer">Khronosの型・成分選択・組み込み関数</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/dx-graphics-hlsl-lerp" target="_blank" rel="noreferrer">Microsoftのlerp</a> · <a href="https://learn.microsoft.com/en-us/windows/win32/direct3dhlsl/dx-graphics-hlsl-saturate" target="_blank" rel="noreferrer">saturate</a></p><p>GLSLの抜粋と同じ色の計算は、HLSLでは次のように表せます。<code>input.uv</code>はVSからのUV、<code>controls.y</code>は0または1、<code>tint.rgb</code>は色の設定です。</p><div class="language-hlsl vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">hlsl</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> base = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">lerp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(input.uv, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.25</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), controls.y);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> float4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(base * tint.rgb, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>言語を変えると、入出力の宣言やリソースを対応付ける書き方も変わります。HLSLの<code>SV_Position</code>や<code>SV_Target</code>、GLSLの<code>in</code>・<code>out</code>などの役割は、<a href="/study/graphics/shader/shader-inputs-and-uniforms.html">シェーダーへ渡すデータ</a>で確認します。</p><h2 id="プログラムと、渡す値を分けて考える" tabindex="-1">プログラムと、渡す値を分けて考える <a class="header-anchor" href="#プログラムと、渡す値を分けて考える" aria-label="Permalink to &quot;プログラムと、渡す値を分けて考える&quot;">​</a></h2><p>アプリは、シェーダーのソースをコンパイルし、使う描画の設定へ組み込みます。描画中に色や移動量を変えるときは、用意したプログラムへ設定値を渡して使えます。実践では、色を変える操作は<code>u_tint</code>、横へ動かす操作は<code>u_offset</code>へ反映します。<a href="/study/graphics/shader/shader-inputs-and-uniforms.html">シェーダーの入力と共通設定</a></p><h2 id="実際に動かす" tabindex="-1">実際に動かす <a class="header-anchor" href="#実際に動かす" aria-label="Permalink to &quot;実際に動かす&quot;">​</a></h2><p><a href="/study/practice/graphics/shader-first-steps.html">シェーダーで三角形の位置と色を変える実践</a>では、GLSLを使って描画し、位置、色、UVの表示を切り替えられます。完全なGLSLと対応するHLSLのコードも、実践側から確認できます。</p><p>材質や画像を読む仕組みは<a href="/study/graphics/basics/materials-textures-and-shaders.html">マテリアル・テクスチャ・シェーダー</a>、各言語の詳しい機能は<a href="/study/graphics/shader/hlsl.html">HLSL</a>と<a href="/study/graphics/shader/glsl.html">GLSL</a>へ進みます。</p>`,26)])])}const E=t(d,[["render",h]]);export{g as __pageData,E as default};
